-- tipo: SQL | Mount de Regras Contabeis em 1 ida (CRS,CONTAS,CR_CONTAS,GESTORES_CR,DRIVERS,CONTA_DRIVERS,EXCECOES,RATEIOS c/ TIPO,RATEIO_ITENS,RATEIO_USOS). Sem params.
SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CODIGO',t.CODIGO,'NOME',t.NOME,'EMPRESA_ID',t.EMPRESA_ID,'ATIVO',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = 'true'),JSON_ARRAY()) AS CRS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CODIGO',t.CODIGO,'NOME',t.NOME,'TIPO',t.TIPO,'NATUREZA',t.NATUREZA,'ATIVO',t.ATIVO)) FROM CONTA_CONTABIL t WHERE 1=1),JSON_ARRAY()) AS CONTAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CR_ID',t.CR_ID,'CONTA_ID',t.CONTA_ID,'ATIVO',t.ATIVO,'CRIADO_EM',t.CRIADO_EM)) FROM CR_CONTA t WHERE t.ATIVO = true),JSON_ARRAY()) AS CR_CONTAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('CR_ID',x.CR_ID,'GESTORES',x.GESTORES)) FROM (SELECT gc.CR_ID, GROUP_CONCAT(g.NOME ORDER BY g.NOME SEPARATOR ', ') AS GESTORES FROM GESTOR_CR gc JOIN GESTOR g ON g.ID = gc.GESTOR_ID WHERE g.ATIVO = 'true' GROUP BY gc.CR_ID) x),JSON_ARRAY()) AS GESTORES_CR,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'DESCRICAO',t.DESCRICAO,'COR',t.COR,'ATIVO',t.ATIVO,'CRIADO_EM',t.CRIADO_EM,'TIPO_DRIVER',t.TIPO_DRIVER,'ORIGEM',t.ORIGEM,'ORDEM',t.ORDEM,'ESCOPO',t.ESCOPO)) FROM DRIVERS t WHERE t.ATIVO = 'true'),JSON_ARRAY()) AS DRIVERS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CONTA_ID',t.CONTA_ID,'DRIVER_ID',t.DRIVER_ID,'CRIADO_EM',t.CRIADO_EM,'PACOTE_ID',t.PACOTE_ID)) FROM CONTA_DRIVER t WHERE 1=1),JSON_ARRAY()) AS CONTA_DRIVERS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CR_ID',t.CR_ID,'CONTA_ID',t.CONTA_ID,'DRIVER_ID',t.DRIVER_ID,'ATIVO',t.ATIVO,'CRIADO_EM',t.CRIADO_EM,'PACOTE_ID',t.PACOTE_ID)) FROM CONTA_DRIVER_EXCECAO t WHERE t.ATIVO = true),JSON_ARRAY()) AS EXCECOES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'DESCRICAO',t.DESCRICAO,'ATIVO',t.ATIVO,'CRIADO_EM',t.CRIADO_EM,'TIPO',t.TIPO)) FROM RATEIO t WHERE t.ATIVO = true),JSON_ARRAY()) AS RATEIOS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'RATEIO_ID',t.RATEIO_ID,'CR_ID',t.CR_ID,'QUANTIDADE',t.QUANTIDADE)) FROM RATEIO_ITEM t WHERE 1=1),JSON_ARRAY()) AS RATEIO_ITENS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('RATEIO_ID',x.RATEIO_ID,'QTD',x.QTD)) FROM (SELECT RATEIO_ID, COUNT(*) AS QTD FROM DRIVER_FORMULA WHERE RATEIO_ID IS NOT NULL GROUP BY RATEIO_ID) x),JSON_ARRAY()) AS RATEIO_USOS